/* World Cities set additions — cards appended after world-cities.js.
   (world-cities.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'world-cities.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('world-cities');
  if (!S) return;
  var extra = [{"name":"Memphis","rarity":"uncommon","id":"memphis","subtitle":"United States","details":"Perched on bluffs above the Mississippi River, Memphis pairs a pyramid on the riverfront with the blues and soul heritage of Beale Street.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Memphis%2C_TN_skyline_along_the_Mississippi_River.jpg?width=1024"},{"name":"Louisville","rarity":"uncommon","id":"louisville","subtitle":"United States","details":"Kentucky's Ohio River city is famed for Churchill Downs and the Kentucky Derby, with a skyline of towers rising behind its historic riverfront.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Louisville%2C_Kentucky_skyline_at_night_%282021%29.jpg?width=1024"},{"name":"Indianapolis","rarity":"uncommon","id":"indianapolis","subtitle":"United States","details":"Indiana's capital is laid out around Monument Circle, its radiating avenues and canal linking a downtown of stadiums, towers, and war memorials.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_of_downtown_Indianapolis_skyline%2C_looking_northeast.jpg?width=1024"},{"name":"Columbus","rarity":"uncommon","id":"columbus","subtitle":"United States","details":"Ohio's capital spreads along the Scioto River, where a rebuilt riverfront of parks and bridges frames the LeVeque Tower and the statehouse.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Columbus_View_from_Main_St_Bridge_-_edit1.jpg?width=1024"},{"name":"Cincinnati","rarity":"uncommon","id":"cincinnati","subtitle":"United States","details":"Set in a bowl of hills on the Ohio River, Cincinnati stacks its skyline above suspension bridges, riverboats, and steep, streetcar-era neighborhoods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Cincinnati_skyline_at_night.jpg?width=1024"},{"name":"Milwaukee","rarity":"uncommon","id":"milwaukee","subtitle":"United States","details":"Wisconsin's lakefront city meets at the junction of three rivers, its brick warehouses, brewery halls, and art museum sails spread along Lake Michigan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Milwaukee_June_2022_50_%28skyline%29.jpg?width=1024"},{"name":"Calgary","rarity":"uncommon","id":"calgary","subtitle":"Canada","details":"Alberta's prairie metropolis rises where the Bow and Elbow rivers meet, the Calgary Tower and Stampede grounds set against a Rocky Mountain horizon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Calgary_Skyline%2C_north_panoramic_view_from_McHugh_Bluff_20240819_1.jpg?width=1024"},{"name":"Edmonton","rarity":"uncommon","id":"edmonton","subtitle":"Canada","details":"Alberta's capital straddles the North Saskatchewan River, its high-rises linked by a vast ribbon of parkland along the river valley's wooded banks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_of_Edmonton_from_the_High_Level_Bridge%2C_Edmonton%2C_Alberta%2C_2026-09-27_01.jpg?width=1024"},{"name":"Ottawa","rarity":"uncommon","id":"ottawa","subtitle":"Canada","details":"Canada's capital gathers around Parliament Hill above the Ottawa River, where Gothic Revival towers overlook the Rideau Canal and its winter skateway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_view_of_Downtown_Ottawa_from_Parliament_Hill_-_July_2010.jpg?width=1024"},{"name":"Halifax","rarity":"uncommon","id":"halifax","subtitle":"Canada","details":"Nova Scotia's capital wraps around one of the world's great natural harbors, its citadel hill sloping down to a boardwalk of ships, towers, and piers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2022-08-15_01_Wide_angle_view_of_Halifax_skyline%2C_Nova_Scotia%2C_Canada.jpg?width=1024"},{"name":"Victoria","rarity":"uncommon","id":"victoria-canada","subtitle":"Canada","details":"British Columbia's capital rings its Inner Harbour with the Parliament Buildings and the Empress Hotel, framed by gardens and snow-capped peaks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Inner_harbor_%2848839803688%29.jpg?width=1024"},{"name":"Winnipeg","rarity":"uncommon","id":"winnipeg","subtitle":"Canada","details":"Manitoba's capital stands at the meeting of the Red and Assiniboine rivers, its Exchange District warehouses rising from the flat northern prairie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Winnipeg%2C_Manitoba_skyline.jpg?width=1024"},{"name":"Montevideo","rarity":"uncommon","id":"montevideo","subtitle":"Uruguay","details":"A laid-back capital on the Río de la Plata, strung along a curving Rambla promenade of beaches, art deco towers and old-town warehouses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_del_Puerto%2C_Montevideo_URU.jpg?width=1024"},{"name":"Asunción","rarity":"uncommon","id":"asuncion","subtitle":"Paraguay","details":"One of South America's oldest capitals, founded on the Paraguay River in 1537, where colonial blocks meet a broad bay and riverfront.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Business_District_162628.jpg?width=1024"},{"name":"La Paz","rarity":"uncommon","id":"la-paz","subtitle":"Bolivia","details":"The world's highest seat of government, spilling down a canyon beneath Illimani, linked by cable cars climbing to El Alto on the rim.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/La_Paz_panorama_December_1_2008.jpg?width=1024"},{"name":"Guayaquil","rarity":"uncommon","id":"guayaquil","subtitle":"Ecuador","details":"Ecuador's great Pacific port on the Guayas River, rebuilt around the Malecón 2000 riverwalk and the pastel hill of Santa Ana.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guayaquil_Panorama_%286719953183%29.jpg?width=1024"},{"name":"Medellín","rarity":"uncommon","id":"medellin","subtitle":"Colombia","details":"A valley city of eternal spring, where Metrocable gondolas climb steep comunas and flowers fill parks between brick tower districts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Medellin-panorama.jpg?width=1024"},{"name":"Brasília","rarity":"uncommon","id":"brasilia","subtitle":"Brazil","details":"A purpose-built modernist capital shaped like an aeroplane, its Monumental Axis lined with Niemeyer's sculptural concrete landmarks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brasilia_Panorama_Exao_Norte_02_2006_128_%2824445905278%29.jpg?width=1024"},{"name":"Salvador","rarity":"uncommon","id":"salvador","subtitle":"Brazil","details":"Brazil's first capital, where the Pelourinho's painted colonial streets overlook All Saints Bay and Afro-Brazilian culture shapes daily life.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salvador_Skyline.jpg?width=1024"},{"name":"Recife","rarity":"uncommon","id":"recife","subtitle":"Brazil","details":"A coastal city woven through rivers, canals and bridges near Olinda, famed for frevo rhythms and the reefs that gave it its name.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_do_Bairro_Boa_Viagem_Recife_Pernambuco_Brasil.jpg?width=1024"},{"name":"Fortaleza","rarity":"uncommon","id":"fortaleza","subtitle":"Brazil","details":"A northeastern beach capital of high-rises along Beira Mar, known for forró music, jangada rafts and trade winds off the Atlantic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_de_Fortaleza.jpg?width=1024"},{"name":"Manaus","rarity":"uncommon","id":"manaus","subtitle":"Brazil","details":"A rubber-boom metropolis deep in the Amazon, where the dark Rio Negro meets the pale Solimões and the ornate opera house recalls its wealth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_de_Manaus.jpg?width=1024"},{"name":"Guatemala City","rarity":"uncommon","id":"guatemala-city","subtitle":"Guatemala","details":"The largest city in Central America, set in a highland valley of ravines, with Mayan Kaminaljuyú ruins folded into its modern districts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_de_Ciudad_de_Guatemala_desde_mirador..jpg?width=1024"},{"name":"San Juan","rarity":"uncommon","id":"san-juan","subtitle":"Puerto Rico","details":"A harbour city where the blue-cobbled streets of Old San Juan, ringed by Spanish forts, meet resort beaches and a modern tower skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_of_San_Juan_architecture_from_across_from_Playita_Condado_%28cropped%29_%28cropped%29.jpg?width=1024"},{"name":"Rabat","rarity":"uncommon","id":"rabat","subtitle":"Morocco","details":"Morocco's capital guards the Bou Regreg river mouth, where the Kasbah of the Udayas and Hassan Tower overlook the Atlantic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Walls%20of%20Kasbah%20of%20Udayas%20and%20new%20Mohammed%20VI%20Tower%20%282024%29.jpg?width=1024"},{"name":"Tangier","rarity":"uncommon","id":"tangier","subtitle":"Morocco","details":"Morocco's gateway city faces Spain across the Strait of Gibraltar, a whitewashed medina descending to a sweeping bay and busy port.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tangier%20pano%20-%20Maged.jpg?width=1024"},{"name":"Alexandria","rarity":"uncommon","id":"alexandria","subtitle":"Egypt","details":"Egypt's Mediterranean city curves around its ancient harbour, where the modern Bibliotheca Alexandrina revives a legendary library.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alexandria%20panorama.jpg?width=1024"},{"name":"Luxor","rarity":"uncommon","id":"luxor","subtitle":"Egypt","details":"Egypt's open-air museum lines both banks of the Nile, its temples and avenues of sphinxes facing the Theban hills across the river.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Luxor%20New%20Corniche%20R03.jpg?width=1024"},{"name":"Aswan","rarity":"uncommon","id":"aswan","subtitle":"Egypt","details":"Egypt's southern Nile city scatters granite islands and feluccas between palm groves, Nubian villages and the great Aswan dams.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aswan%20Nile%20Panorama%20R01.jpg?width=1024"},{"name":"Khartoum","rarity":"uncommon","id":"khartoum","subtitle":"Sudan","details":"Sudan's capital stands where the Blue Nile and White Nile meet, a low-rise desert city divided by broad river bridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hartum%20ve%20Mavi%20Nil.jpg?width=1024"},{"name":"Kampala","rarity":"uncommon","id":"kampala","subtitle":"Uganda","details":"Uganda's capital rolls across green hills near Lake Victoria, its skyline framed by the Kasubi Tombs and Bahai Temple hill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kampala%20skyline.jpg?width=1024"},{"name":"Kigali","rarity":"uncommon","id":"kigali","subtitle":"Rwanda","details":"Rwanda's capital spreads across a series of ridges and valleys, a famously orderly hill city of red earth and terraced gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kigali%20skyline.jpg?width=1024"},{"name":"Lusaka","rarity":"uncommon","id":"lusaka","subtitle":"Zambia","details":"Zambia's capital sits on a limestone plateau, a garden city of broad avenues, markets and jacaranda trees at its centre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lusaka%20Transport%20in%20OLD%20PICTURE%20-%202020.jpg?width=1024"},{"name":"Harare","rarity":"uncommon","id":"harare","subtitle":"Zimbabwe","details":"Zimbabwe's capital, the Sunshine City, is known for wide avenues shaded by jacarandas and flamboyants in the highveld light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Joina%20City4.jpg?width=1024"},{"name":"Maputo","rarity":"uncommon","id":"maputo","subtitle":"Mozambique","details":"Mozambique's capital overlooks Maputo Bay, its acacia avenues and iron Eiffel-era buildings facing the Indian Ocean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/60%20Skyline%20%2836931644911%29.jpg?width=1024"},{"name":"Antananarivo","rarity":"uncommon","id":"antananarivo","subtitle":"Madagascar","details":"Madagascar's capital climbs a rocky ridge above rice paddies and Lake Anosy, crowned by the terraced palaces of the old city.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20of%20Antananarivo%20%283953594664%29.jpg?width=1024"},{"name":"Adelaide","rarity":"uncommon","id":"adelaide","subtitle":"Australia","details":"South Australia's planned capital, laid out in 1836 as a neat grid ringed by parklands on the River Torrens, famed for festivals, churches and wine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adelaide%20skyline%2C%20December%202022.jpg?width=1024"},{"name":"Canberra","rarity":"uncommon","id":"canberra","subtitle":"Australia","details":"Australia's purpose-built capital, designed by Walter Burley Griffin around a broad central lake, its avenues radiating between wooded hills and ridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20of%20Canberra%20from%20Mount%20Ainslie.jpg?width=1024"},{"name":"Darwin","rarity":"uncommon","id":"darwin","subtitle":"Australia","details":"Tropical capital of the Northern Territory on a vast harbour, rebuilt after wartime raids and Cyclone Tracy, gateway to Kakadu and Top End wetlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Darwin%20%28AU%29%2C%20Darwin%20Waterfront%20--%202019%20--%204429-31.jpg?width=1024"},{"name":"Christchurch","rarity":"uncommon","id":"christchurch","subtitle":"New Zealand","details":"Garden city on New Zealand's South Island, founded in 1850 beside the Avon River, known for its Gothic cathedral, punting boats and English-style parks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20of%20northern%20parts%20of%20Christchurch%20Central%20City%2C%20New%20Zealand.jpg?width=1024"},{"name":"Dunedin","rarity":"uncommon","id":"dunedin","subtitle":"New Zealand","details":"Scottish-founded city on Otago Harbour, enriched by the 1860s gold rushes, noted for grand Victorian stone buildings and famously steep residential streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dunedin%20city%20after%20sunset%20from%20Signal%20Hill.jpg?width=1024"},{"name":"Suva","rarity":"uncommon","id":"suva","subtitle":"Fiji","details":"Fiji's capital since 1882, a busy harbour city on Viti Levu's southeast coast of colonial buildings, produce markets and gardens facing the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suva%2C%20Fiji%2052.jpg?width=1024"},{"name":"Machu Picchu","rarity":"uncommon","id":"machu-picchu","subtitle":"Peru","details":"Fifteenth-century Inca royal estate high in the Peruvian Andes, its dry-stone temples and terraces aligned to sacred peaks above the Urubamba gorge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Machu%20Picchu%2C%20Per%C3%BA%2C%202015-07-30%2C%20DD%2047.JPG?width=1024"},{"name":"Tikal","rarity":"uncommon","id":"tikal","subtitle":"Guatemala","details":"One of the greatest Maya cities, flourishing for over a millennium in the Guatemalan rainforest, its steep limestone pyramids towering over the canopy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gran%20Plaza%20with%20Temple%20I%20-%20Tikal%20Archaeological%20Site%20-%20Peten%20-%20Guatemala%20%2815684347430%29.jpg?width=1024"},{"name":"Angkor","rarity":"uncommon","id":"angkor","subtitle":"Cambodia","details":"Vast Khmer capital region built between the 9th and 15th centuries around immense temple-mountains, moated enclosures, reservoirs and forest causeways.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Angkor%20Wat%20Panorama%202012.jpg?width=1024"},{"name":"Ghent","rarity":"common","id":"ghent","subtitle":"Belgium","details":"Ghent in Flanders gathers canals, guild houses and the Gravensteen castle around St Bavo's Cathedral, a medieval port city between Brussels and Bruges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ghent_skyline_%2828400400954%29.jpg?width=1024"},{"name":"Graz","rarity":"common","id":"graz","subtitle":"Austria","details":"Graz, Austria's second city, climbs to the Schlossberg clock tower above a Renaissance old town and the red roofs along the River Mur in Styria.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Graz%2C_Austria_skyline_-_July_2004.jpg?width=1024"},{"name":"Faro","rarity":"common","id":"faro","subtitle":"Portugal","details":"Faro faces the lagoons of the Ria Formosa in Portugal's Algarve, a walled old town of whitewashed lanes, stork nests and a working marina.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Faro%2C_Algarve_%2832572663705%29.jpg?width=1024"},{"name":"Coimbra","rarity":"common","id":"coimbra","subtitle":"Portugal","details":"Coimbra rises in terraces above Portugal's Mondego River, crowned by one of Europe's oldest universities and a medieval old town of steep lanes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coimbra_e_o_rio_Mondego_%286167200429%29_%28cropped%29.jpg?width=1024"},{"name":"Braga","rarity":"common","id":"braga","subtitle":"Portugal","details":"Braga in northern Portugal is a city of Baroque churches and gardens, famed for the Bom Jesus do Monte sanctuary's zigzag stairway on its hill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arcada_in_Braga_01.jpg?width=1024"},{"name":"Toledo","rarity":"common","id":"toledo","subtitle":"Spain","details":"Toledo crowns a granite hill in a bend of the Tagus in Spain, a walled city where Christian, Muslim and Jewish monuments share medieval streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Toledo_Skyline_Panorama%2C_Spain_-_Dec_2006.jpg?width=1024"},{"name":"Salamanca","rarity":"common","id":"salamanca","subtitle":"Spain","details":"Salamanca glows gold from its local sandstone in western Spain, home to an ancient university, twin cathedrals and a grand arcaded Plaza Mayor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salamanca_Skyline_%283340154424%29.jpg?width=1024"},{"name":"León","rarity":"common","id":"leon","subtitle":"Spain","details":"León in northwest Spain is famed for its Gothic cathedral's stained glass, Roman walls and the old pilgrim road of the Camino de Santiago.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2008-07-09_Plaza_Mayor_de_Le%C3%B3n%2C_Espa%C3%B1a.jpg?width=1024"},{"name":"Palma","rarity":"common","id":"palma","subtitle":"Spain","details":"Palma rises over its bay in Mallorca, where a vast Gothic cathedral stands above honey-stone lanes, courtyards and a marina of the western Mediterranean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palma_Maritimo_atardecer.jpg?width=1024"},{"name":"Strasbourg","rarity":"common","id":"strasbourg","subtitle":"France","details":"Strasbourg sits on Rhine-border islands in Alsace, its Grande Île of half-timbered lanes circling a pink-sandstone Gothic cathedral of famous spire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%2C_Strasbourg.jpg?width=1024"},{"name":"Nantes","rarity":"common","id":"nantes","subtitle":"France","details":"Nantes spreads along the Loire in western France, a former Breton capital and shipbuilding port of châteaux, quays and inventive river islands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nantes_aerial_skyline_view.jpg?width=1024"},{"name":"Toulouse","rarity":"common","id":"toulouse","subtitle":"France","details":"Toulouse, the Pink City of southwest France, lines the Garonne and Canal du Midi with rose-brick churches, capitole squares and aerospace workshops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Toulouse_-_Garonne_Skyline_at_Sunset_-_2012-02-22.jpg?width=1024"},{"name":"Montpellier","rarity":"common","id":"montpellier","subtitle":"France","details":"Montpellier in southern France mixes a medieval core of lanes and mansions with bold modern districts stretching toward the Mediterranean shore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_depuis_l%27Arc_de_Triomphe_de_Montpellier_-1.jpg?width=1024"},{"name":"Turin","rarity":"common","id":"turin","subtitle":"Italy","details":"Turin lines the Po beneath the Alps in Piedmont, an elegant city of arcades, Savoy palaces and the spire of the Mole Antonelliana over its grid.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Turin_skyline_from_Monte_dei_Cappuccini_Turin.jpeg?width=1024"},{"name":"Bologna","rarity":"common","id":"bologna","subtitle":"Italy","details":"Bologna in Emilia-Romagna is a city of red roofs, medieval towers and endless porticoes, home to Europe's oldest university and famed kitchens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_of_Bologna_against_the_sunset.jpg?width=1024"},{"name":"Genoa","rarity":"common","id":"genoa","subtitle":"Italy","details":"Genoa climbs in terraces from its old port on the Ligurian Sea, a maritime republic's maze of caruggi lanes, palaces and a major aquarium.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/File-Porto_Antico_Genova_varie_09.jpg?width=1024"},{"name":"Verona","rarity":"common","id":"verona","subtitle":"Italy","details":"Verona wraps around the Adige in the Veneto, where a Roman arena, medieval bridges and Romeo-and-Juliet lore fill its pink-marble streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Verona_di_notte.jpg?width=1024"},{"name":"Pisa","rarity":"common","id":"pisa","subtitle":"Italy","details":"Pisa on the Arno in Tuscany is famed for its leaning campanile in the Piazza dei Miracoli, beside a Romanesque cathedral and baptistery of white marble.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Pisa_2.jpg?width=1024"},{"name":"Siena","rarity":"common","id":"siena","subtitle":"Italy","details":"Siena crowns Tuscan hills with a fan-shaped Piazza del Campo, a striped marble cathedral and contrada neighbourhoods that race the Palio horse race.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Siena_skyline_%2820883710323%29.jpg?width=1024"},{"name":"Split","rarity":"common","id":"split","subtitle":"Croatia","details":"Split grew inside the vast palace of Roman emperor Diocletian on Croatia's Dalmatian coast, its lanes and squares fronting an Adriatic harbour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Split_iz_zraka.jpg?width=1024"},{"name":"Sarajevo","rarity":"common","id":"sarajevo","subtitle":"Bosnia and Herzegovina","details":"Sarajevo fills a valley of the Miljacka River in Bosnia, where Ottoman bazaars, mosques, churches and Austro-Hungarian avenues meet beneath green hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sarajevo_Night_Skyline_Bosnia_%26_Herzegovina_2014_%2815510458883%29.jpg?width=1024"},{"name":"Mostar","rarity":"common","id":"mostar","subtitle":"Bosnia and Herzegovina","details":"Mostar in Herzegovina is named for the bridge-keepers of Stari Most, the Ottoman arch over the emerald Neretva rebuilt stone by stone after wartime ruin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stari_Most%2C_Mostar_%28Bosnia_Herzegovina%29.jpg?width=1024"},{"name":"Kotor","rarity":"common","id":"kotor","subtitle":"Montenegro","details":"Kotor hides at the head of a fjord-like bay in Montenegro, a walled Venetian town of palaces and churches beneath fortress walls climbing the cliffs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kotor_and_Boka_kotorska_-_view_from_city_wall.jpg?width=1024"},{"name":"Skopje","rarity":"common","id":"skopje","subtitle":"North Macedonia","details":"Skopje spreads along the Vardar River in North Macedonia, mixing an Ottoman old bazaar, a stone bridge and grand neoclassical squares beneath Mt Vodno.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skopje_skyline_%288172281513%29.jpg?width=1024"},{"name":"Tirana","rarity":"common","id":"tirana","subtitle":"Albania","details":"Tirana, Albania's capital, mixes Ottoman, Italian-era and modern blocks around Skanderbeg Square, with Mount Dajti rising green behind the city.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tirana_skyline_at_night.jpg?width=1024"},{"name":"Poznan","rarity":"common","id":"poznan","subtitle":"Poland","details":"Poznań in western Poland is one of the country's oldest cities, its old market square ringed by colourful merchant houses and a Renaissance town hall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Pozna%C5%84_%C5%81azarz.jpg?width=1024"},{"name":"Wroclaw","rarity":"common","id":"wroclaw","subtitle":"Poland","details":"Wrocław spreads over Oder islands in Silesia, a Gothic old town of cathedral spires, market squares and hundreds of small bridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ostr%C3%B3w_Tumski_Wroc%C5%82aw_-_zesp%C3%B3%C5%82_budynk%C3%B3w_sakralnych.jpg?width=1024"},{"name":"Brno","rarity":"common","id":"brno","subtitle":"Czechia","details":"Brno in Moravia pairs a medieval old town and Špilberk Castle hill with the modernist Villa Tugendhat, in the Czech Republic's wine-growing south.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brno_%C5%A0pilberk_Castle_-_55526012366.jpg?width=1024"},{"name":"Kosice","rarity":"common","id":"kosice","subtitle":"Slovakia","details":"Košice in eastern Slovakia centres on a broad main street of burgher houses and St Elisabeth's Cathedral, a Gothic landmark near the Hungarian border.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%A1ice_Hlavn%C3%A1.jpg?width=1024"},{"name":"Debrecen","rarity":"common","id":"debrecen","subtitle":"Hungary","details":"Debrecen on Hungary's Great Plain is famed for its Great Reformed Church, thermal baths and the flower-filled avenues of the country's east.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Debrecen_-_Protestant_Great_Church1.jpg?width=1024"},{"name":"Tromsø","rarity":"common","id":"troms","subtitle":"Norway","details":"Tromsø sits on an island far above the Arctic Circle in Norway, a gateway for northern-lights watchers with the Arctic Cathedral across its bridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Troms%C3%B8_from_Fjellheisen.jpg?width=1024"},{"name":"Stavanger","rarity":"common","id":"stavanger","subtitle":"Norway","details":"Stavanger on Norway's southwest coast keeps rows of white wooden cottages in its old town beside a harbour shaped by fishing, shipping and oil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stavanger_aerial_3.jpg?width=1024"},{"name":"Trondheim","rarity":"common","id":"trondheim","subtitle":"Norway","details":"Trondheim on its fjord in central Norway grew around Nidaros Cathedral, a Gothic pilgrimage church above the Nidelva river and colourful wharves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2018-06-09_10-54-45_Norwegen_Trondheim_Bakklandet.jpg?width=1024"},{"name":"Odense","rarity":"common","id":"odense","subtitle":"Denmark","details":"Odense on Denmark's Funen island is Hans Christian Andersen's hometown, a city of half-timbered lanes, St Canute's Cathedral and leafy river parks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Port_of_Odense_and_the_City_Island.JPG?width=1024"},{"name":"Exeter","rarity":"common","id":"exeter","subtitle":"United Kingdom","details":"Exeter in Devon stands on the River Exe, a cathedral city with Roman walls, medieval vaults and a historic quay near England's southwest coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Exeter_panorama_1.jpg?width=1024"},{"name":"Vientiane","rarity":"common","id":"vientiane","subtitle":"Laos","details":"Laos' laid-back capital on a bend of the Mekong, marked by the golden That Luang stupa, the Patuxai arch and riverside night markets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown%20Vientiane%2C%20Laos%202003.jpg?width=1024"},{"name":"Phnom Penh","rarity":"common","id":"phnom-penh","subtitle":"Cambodia","details":"Cambodia's capital where the Tonle Sap meets the Mekong, famed for the Royal Palace, Silver Pagoda and French colonial boulevards.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Barges%20on%20the%20Tonle%20Sap%20river%2C%20Phnom%20Penh%2C%20Cambodia.jpg?width=1024"},{"name":"Bandar Seri Begawan","rarity":"common","id":"bandar-seri-begawan","subtitle":"Brunei","details":"Brunei's river capital, where the golden-domed Omar Ali Saifuddien Mosque rises beside Kampong Ayer, a vast village built on stilts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pusat%20Bandar%2C%20Brunei%20skyline.jpg?width=1024"},{"name":"Dili","rarity":"common","id":"dili","subtitle":"Timor-Leste","details":"Timor-Leste's coastal capital, stretched along a wide bay beneath dry hills, marked by the Cristo Rei statue on its eastern headland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/034%20Dili%20waterfront%2C%20Timor%201971%20%2851243843987%29.jpg?width=1024"},{"name":"Malacca","rarity":"common","id":"malacca","subtitle":"Malaysia","details":"Historic Malaysian strait port where Dutch, Portuguese and Peranakan heritage lines the riverbanks around red-walled Dutch Square.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/George%20Town%2C%20Penang%2C%20Malaysia.jpg?width=1024"},{"name":"Ipoh","rarity":"common","id":"ipoh","subtitle":"Malaysia","details":"Malaysian city ringed by white limestone hills, famed for cave temples, colonial Old Town lanes, white coffee and bean sprout dishes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ipoh%20skyline.jpg?width=1024"},{"name":"Medan","rarity":"common","id":"medan","subtitle":"Indonesia","details":"North Sumatra's bustling gateway city, a Dutch colonial trading hub famed for the Maimun Palace, its Great Mosque and trips to Lake Toba.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Medan%20skyline%20%282022%29.jpg?width=1024"},{"name":"Makassar","rarity":"common","id":"makassar","subtitle":"Indonesia","details":"South Sulawesi's great harbour city on the Makassar Strait, famed for sunset promenades at Losari Beach and spicy seafood soups.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/TransStudio%20far.JPG?width=1024"},{"name":"Davao","rarity":"common","id":"davao","subtitle":"Philippines","details":"Philippine city on Mindanao's Davao Gulf beneath Mount Apo, famed for durian, orchids and the Philippine Eagle Centre in its foothills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Davao%20Agdao%20skyline%20%28Davao%20City%3B%2004-22-2024%29.jpg?width=1024"},{"name":"Tainan","rarity":"common","id":"tainan","subtitle":"Taiwan","details":"Taiwan's oldest city, founded as a Dutch outpost, famed for Fort Zeelandia, Confucian temples, Chihkan Tower and snack-filled lanes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20nearby%20Tainan%20Train%20Station.jpg?width=1024"},{"name":"Taichung","rarity":"common","id":"taichung","subtitle":"Taiwan","details":"Central Taiwan city of broad boulevards and night markets, famed for bubble tea, the painted Rainbow Village and Gaomei wetland sunsets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Taichung%20Skyline.jpg?width=1024"},{"name":"Nara","rarity":"common","id":"nara","subtitle":"Japan","details":"Japan's first permanent capital, founded in 710, famed for the Great Buddha of Todai-ji and the tame deer roaming through Nara Park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20panorama%20of%20Nara%20Park.jpg?width=1024"},{"name":"Hiroshima","rarity":"common","id":"hiroshima","subtitle":"Japan","details":"City of rivers in western Japan, rebuilt around Peace Memorial Park and the Atomic Bomb Dome, gateway to the Miyajima island shrine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hiroshima%20skyline.jpg?width=1024"},{"name":"Nagasaki","rarity":"common","id":"nagasaki","subtitle":"Japan","details":"Hillside port city curving around a long harbour in Kyushu, shaped by Dutch and Chinese traders, famed for its night view and champon noodles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20190202%20Nagasaki%20skyline-1.jpg?width=1024"},{"name":"Kanazawa","rarity":"common","id":"kanazawa","subtitle":"Japan","details":"Castle city on Japan's Sea of Japan coast, famed for Kenrokuen garden, preserved samurai and geisha districts and gold leaf craft.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20of%20Kanazawa%2C%20Ishikawa%20from%20Castle%20Inn%20Kanazawa.JPG?width=1024"},{"name":"Sendai","rarity":"common","id":"sendai","subtitle":"Japan","details":"Tohoku's City of Trees, founded by Date Masamune, where broad zelkova avenues spread from Aoba Castle hill toward the Pacific plain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sendai%20skyline%20and%20Hirose%20River%20from%20Hyojogawara%20Bridge.jpg?width=1024"},{"name":"Harbin","rarity":"common","id":"harbin","subtitle":"China","details":"Northeast China's ice city on the Songhua River, famed for Russian-era streets, Saint Sophia Cathedral and its winter ice festival.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jihong%20Bridge%20and%20Skyline%20of%20Daoli%26Daowai%20District%2CHarbin%2020251021.jpg?width=1024"},{"name":"Dalian","rarity":"common","id":"dalian","subtitle":"China","details":"Liaoning port city on a hilly peninsula between the Yellow Sea and Bohai Bay, famed for grand squares, beaches and Russian-era avenues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dalian%20Skyline.jpg?width=1024"},{"name":"Qingdao","rarity":"common","id":"qingdao","subtitle":"China","details":"Shandong port city famed for Tsingtao beer, German-era old town rooftops, Laoshan mountain and piers reaching into the Yellow Sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Qingdao%20-%20Drone%20view%20city%20with%20skyline%20%28Unsplash%29.jpg?width=1024"},{"name":"Nanjing","rarity":"common","id":"nanjing","subtitle":"China","details":"Ancient capital on the Yangtze, ringed by Ming dynasty city walls and Purple Mountain tombs, famed for the Sun Yat-sen Mausoleum parklands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nanjing%20-%20Skyline%20from%20Xuanwu%20Lake.jpg?width=1024"},{"name":"Wuhan","rarity":"common","id":"wuhan","subtitle":"China","details":"Central China port where the Han River meets the Yangtze, famed for the Yellow Crane Tower, wide bridges and vast East Lake parkland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20of%20Wuhan-2.jpg?width=1024"},{"name":"Kunming","rarity":"common","id":"kunming","subtitle":"China","details":"Yunnan's Spring City, a mild highland capital beside Dianchi Lake famed for flowers, the Stone Forest and old railway quarter streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kunming.%E6%98%86%E6%98%8E.skyline.sunset.2013.jpg?width=1024"},{"name":"Guilin","rarity":"common","id":"guilin","subtitle":"China","details":"Guangxi city famed worldwide for its Li River scenery, where steep karst limestone peaks rise from green plains and rice fields.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guilin%20city%20panorama%20%288475636764%29.jpg?width=1024"},{"name":"Kochi","rarity":"common","id":"kochi","subtitle":"India","details":"Kerala port city of islands and backwaters, famed for Chinese fishing nets at Fort Kochi, spice godowns and Dutch-era Mattancherry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/High%20Court%20Water%20Metro%20Terminal%20and%20Marine%20Drive%20Skyline%20Kochi%202026-09-06.jpg?width=1024"},{"name":"Mysore","rarity":"common","id":"mysore","subtitle":"India","details":"Karnataka's royal city beneath Chamundi Hill, famed for the illuminated Mysore Palace, silk, sandalwood and Dasara festival parades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20entire%20Mysore%20city%20from%20Chamunda%20Hills%2C%20Mysore.JPG?width=1024"},{"name":"Amritsar","rarity":"common","id":"amritsar","subtitle":"India","details":"Punjab's holy city, home to the Golden Temple reflected in its sacred pool, close to the Wagah border ceremony with Pakistan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golden%20temple%20aerial%20shot%20in%20Amritsar.jpg?width=1024"},{"name":"Lucknow","rarity":"common","id":"lucknow","subtitle":"India","details":"Uttar Pradesh city on the Gomti River, famed for Nawabi palaces, the Bara Imambara labyrinth, chikan embroidery and Awadhi cuisine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lucknow%20Skyline%20From%20Gomti%20Nagar.jpg?width=1024"},{"name":"Agra","rarity":"common","id":"agra","subtitle":"India","details":"City on the Yamuna in Uttar Pradesh, famed across the world for the Taj Mahal, Agra Fort and the marble inlay craft of Mughal emperors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aks%20The%20Reflection%20Taj%20Mahal.jpg?width=1024"},{"name":"Jodhpur","rarity":"common","id":"jodhpur","subtitle":"India","details":"Rajasthan's Blue City, where indigo-washed houses cluster beneath the massive Mehrangarh Fort on its rocky hill above the Thar desert edge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jodhpur%20Skyline.jpg?width=1024"},{"name":"Kuwait City","rarity":"common","id":"kuwait-city","subtitle":"Kuwait","details":"Gulf capital on Kuwait Bay, famed for the Kuwait Towers, dhow harbours, the Grand Mosque and a corniche of white towers and beaches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kuwait%20City%20Skyline%20%285023996893%29.jpg?width=1024"},{"name":"Manama","rarity":"common","id":"manama","subtitle":"Bahrain","details":"Bahrain's island capital on the Gulf, blending the old Manama Souq and a Portuguese fort with the twin sail towers of its harbour skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manama%20Manama%20Skyline%2004.jpg?width=1024"},{"name":"Jeddah","rarity":"common","id":"jeddah","subtitle":"Saudi Arabia","details":"Saudi Red Sea gateway for Hajj pilgrims, famed for Al-Balad's coral-stone houses, the Corniche and one of the world's tallest fountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jeddah%20Corniche%20at%20night.jpg?width=1024"},{"name":"Antalya","rarity":"common","id":"antalya","subtitle":"Turkey","details":"Turkish Riviera city where Roman Hadrian's Gate and the old Kaleiçi lanes overlook yacht marinas beneath the Taurus Mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Antalya%2C%20Turkey%20skyline%2019%20February%202022.jpg?width=1024"},{"name":"Izmir","rarity":"common","id":"izmir","subtitle":"Turkey","details":"Aegean port city in Turkey around a wide bay, famed for its Kordon promenade, Kemeralti bazaar, clock tower and the ruins of Ephesus nearby.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Izmir%20k%C3%B6rfezi.jpg?width=1024"},{"name":"Bishkek","rarity":"common","id":"bishkek","subtitle":"Kyrgyzstan","details":"Kyrgyzstan's leafy capital beneath the Ala-Too mountains, a grid of Soviet avenues and oak parks near the Ala Archa gorge trailheads.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bishkek%2C%20Kyrgyzstan%20%2830791780198%29.jpg?width=1024"},{"name":"Anchorage","rarity":"common","id":"anchorage","subtitle":"United States","details":"Alaska's largest city fills a bowl between Cook Inlet and the Chugach Mountains, its downtown grid laid out on land first claimed by railroad builders.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anchorage%2C_Alaska.jpg?width=1024"},{"name":"Juneau","rarity":"common","id":"juneau","subtitle":"United States","details":"Alaska's capital clings to a narrow strip between Gastineau Channel and steep, forested peaks, reachable only by boat or plane despite its city streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Juneau_from_the_air_%285869741449%29.jpg?width=1024"},{"name":"Spokane","rarity":"common","id":"spokane","subtitle":"United States","details":"Washington's river city is built around the falls of the Spokane River, where a skyride crosses the gorge below a downtown of brick and stone towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spokane%2C_Washington_skyline.jpg?width=1024"},{"name":"Eugene","rarity":"common","id":"eugene","subtitle":"United States","details":"Oregon's Willamette Valley city spreads beneath Skinner Butte along its namesake river, a green grid of bridges, bike paths, and university grounds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Eugene%2C_Oregon_from_Skinner_Butte.jpg?width=1024"},{"name":"Fresno","rarity":"common","id":"fresno","subtitle":"United States","details":"The agricultural heart of California's San Joaquin Valley, Fresno spreads across flat farmland with the Sierra Nevada foothills on its eastern horizon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fresno.jpg?width=1024"},{"name":"Santa Barbara","rarity":"common","id":"santa-barbara","subtitle":"United States","details":"California's 'American Riviera' curves along a south-facing bay beneath the Santa Ynez Mountains, all white stucco, red tile roofs, and palm-lined shores.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USA-Santa_Barbara-View_from_County_Courthouse_Tower-8.jpg?width=1024"},{"name":"Palm Springs","rarity":"common","id":"palm-springs","subtitle":"United States","details":"A desert resort city at the foot of Mount San Jacinto, Palm Springs lines its palm-shaded avenues with mid-century modern houses and golf-green lawns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palm_Springs%2C_CA.jpg?width=1024"},{"name":"Scottsdale","rarity":"common","id":"scottsdale","subtitle":"United States","details":"Arizona's desert city stretches beneath Camelback Mountain, blending an Old Town of western storefronts with resorts, canals, and saguaro-dotted hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scottsdale%2C_Arizona.jpg?width=1024"},{"name":"Flagstaff","rarity":"common","id":"flagstaff","subtitle":"United States","details":"Arizona's mountain town sits in ponderosa pine forest at the base of the San Francisco Peaks, its brick downtown threaded by historic Route 66.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flagstaff_downtown_SFmtn.jpg?width=1024"},{"name":"El Paso","rarity":"common","id":"el-paso","subtitle":"United States","details":"Texas's westernmost city fills a Rio Grande pass beneath the Franklin Mountains, facing Ciudad Juarez across one of the continent's oldest borderlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/El_Paso_skyline.jpg?width=1024"},{"name":"San Antonio","rarity":"common","id":"san-antonio","subtitle":"United States","details":"Texas's old Spanish colonial city winds along its River Walk below the downtown towers, anchored by the Alamo and a ring of 18th-century missions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_San_Antonio%2C_Texas_%2812212839743%29.jpg?width=1024"},{"name":"Oklahoma City","rarity":"common","id":"oklahoma-city","subtitle":"United States","details":"Oklahoma's capital spreads across the plains around a skyline anchored by the Devon Tower, with the Oklahoma River and Bricktown canal below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Oklahoma_City_skyline_%282%29.jpg?width=1024"},{"name":"Tulsa","rarity":"common","id":"tulsa","subtitle":"United States","details":"Oklahoma's Arkansas River city is a treasury of Art Deco towers built on oil wealth, its skyline reflected in the river at Gathering Place park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tulsa_skyline_aerial%2C_April_2023.jpg?width=1024"},{"name":"Little Rock","rarity":"common","id":"little-rock","subtitle":"United States","details":"Arkansas's capital lines the south bank of the Arkansas River, its skyline and river market district linked by bridges to the north shore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Little_Rock_pano.jpg?width=1024"},{"name":"Des Moines","rarity":"common","id":"des-moines","subtitle":"United States","details":"Iowa's capital pairs a gold-domed statehouse on its hill with a downtown skyline along the Des Moines River, surrounded by rolling farmland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Fireworks.jpg?width=1024"},{"name":"Omaha","rarity":"common","id":"omaha","subtitle":"United States","details":"Nebraska's Missouri River city grew from a frontier ferry landing into a skyline of towers above the riverfront, stockyards, and brick warehouse districts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Omaha_from_Heartland_of_America_Park%2C_July_2026.jpg?width=1024"},{"name":"Wichita","rarity":"common","id":"wichita","subtitle":"United States","details":"Kansas's largest city stands where the Arkansas and Little Arkansas rivers join, marked by the Keeper of the Plains statue at their confluence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Wichita_From_Lincoln.jpg?width=1024"},{"name":"Grand Rapids","rarity":"common","id":"grand-rapids","subtitle":"United States","details":"Michigan's second city straddles the Grand River, its downtown towers and blue footbridges rising above a valley long known for furniture making.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand_Rapids%2C_Michigan_skyline_May_2022.jpg?width=1024"},{"name":"Madison","rarity":"common","id":"madison","subtitle":"United States","details":"Wisconsin's capital fills an isthmus between Lakes Mendota and Monona, its domed statehouse visible for miles over the water and tree-lined streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Madison_WI%2C_Lake_Monona_Dec04_IMG_2933.jpg?width=1024"},{"name":"Providence","rarity":"common","id":"providence","subtitle":"United States","details":"Rhode Island's capital threads its downtown along the Providence River, where WaterFire braziers light a skyline of brick mills and modern towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Providence_buildings_and_Providence_River_-_51767023532.jpg?width=1024"},{"name":"Hartford","rarity":"common","id":"hartford","subtitle":"United States","details":"Connecticut's capital rises along the Connecticut River, its skyline mixing the gold-domed capitol, the Travelers Tower, and old insurance halls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hartford_skyline.jpg?width=1024"},{"name":"Bangor","rarity":"common","id":"bangor","subtitle":"United States","details":"A Maine lumber port on the Penobscot River, Bangor stacks its brick downtown and church steeples above a waterfront once crowded with timber schooners.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bangor%2C_Maine.jpg?width=1024"},{"name":"Burlington","rarity":"common","id":"burlington","subtitle":"United States","details":"Vermont's largest city terraces down to Lake Champlain from Church Street's brick marketplace, facing the Adirondack Mountains across the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Church_Street_Marketplace_Burlington_Vermont_looking_north_from_Main_Street.jpg?width=1024"},{"name":"Asheville","rarity":"common","id":"asheville","subtitle":"United States","details":"A North Carolina city cradled by the Blue Ridge Mountains, Asheville pairs an Art Deco downtown with the vast Biltmore estate on the French Broad River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Asheville_North_Carolina_aerial_panorama_at_sunset_with_McCormick_Field.jpg?width=1024"},{"name":"Knoxville","rarity":"common","id":"knoxville","subtitle":"United States","details":"Tennessee's river city spreads along the Tennessee River beneath the Great Smoky Mountains, its skyline marked by the golden Sunsphere of the 1982 fair.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Knoxville_skyline_from_Tennessee_River.jpg?width=1024"},{"name":"Birmingham","rarity":"common","id":"birmingham","subtitle":"United States","details":"Alabama's steel city fills a valley between red ore mountains, its downtown towers watched over by the iron Vulcan statue on Red Mountain's crest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Birmingham%2C_AL.jpg?width=1024"},{"name":"Jackson","rarity":"common","id":"jackson","subtitle":"United States","details":"Mississippi's capital rises along the Pearl River, its skyline anchored by the state capitol dome and a downtown shaped by civil rights history.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JacksonMS_Downtown_Panorama.jpg?width=1024"},{"name":"Bismarck","rarity":"common","id":"bismarck","subtitle":"United States","details":"North Dakota's capital spreads across Missouri River bluffs, its Art Deco capitol tower - the 'Skyscraper on the Prairie' - visible for miles around.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bismarck%2C_North_Dakota_aerial_view.jpg?width=1024"},{"name":"Sioux Falls","rarity":"common","id":"sioux-falls","subtitle":"United States","details":"South Dakota's largest city is named for the quartzite falls of the Big Sioux River, which tumble through Falls Park at the edge of its downtown.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Sioux_Falls_and_Falls_Park.jpg?width=1024"},{"name":"Billings","rarity":"common","id":"billings","subtitle":"United States","details":"Montana's largest city spreads beneath sandstone Rimrocks along the Yellowstone River, a rail and ranching hub on the northern plains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Billings_MT_skyline.jpg?width=1024"},{"name":"Cheyenne","rarity":"common","id":"cheyenne","subtitle":"United States","details":"Wyoming's capital pairs a gold-domed statehouse with a frontier-era rail depot, its wide streets laid out on the high plains east of the Laramie Range.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Cheyenne%2C_Wyoming_%2828169024324%29.jpg?width=1024"},{"name":"Nassau","rarity":"common","id":"nassau","subtitle":"Bahamas","details":"A harbour capital on New Providence, once a pirate republic, where pastel government buildings face straw markets and Paradise Island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cable_Beach_SkyLine_-_panoramio.jpg?width=1024"},{"name":"Bridgetown","rarity":"common","id":"bridgetown","subtitle":"Barbados","details":"Barbados' capital on Carlisle Bay, a port of coral-stone warehouses, a historic garrison and one of the oldest synagogues in the Americas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bridgetown_Promenade.jpg?width=1024"},{"name":"Port of Spain","rarity":"common","id":"port-of-spain","subtitle":"Trinidad and Tobago","details":"A Gulf of Paria capital framed by the Northern Range, famed for Carnival, the Magnificent Seven mansions and its great Savannah park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/POS_SKYLINE_2024_BEAUTIFUL_EVAN-P_2024_10-8.jpg?width=1024"},{"name":"San Salvador","rarity":"common","id":"san-salvador","subtitle":"El Salvador","details":"A capital in a volcanic valley beneath San Salvador volcano, rebuilt many times after earthquakes, with pupusas as its beloved staple.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Complete_Skyline_2011.jpg?width=1024"},{"name":"Tegucigalpa","rarity":"common","id":"tegucigalpa","subtitle":"Honduras","details":"A mountain capital split across steep hills and the Choluteca River, joined with twin city Comayagüela in a bowl of pine-covered ridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_panorama_of_Tegucigalpa%2C_Honduras.jpg?width=1024"},{"name":"Managua","rarity":"common","id":"managua","subtitle":"Nicaragua","details":"A lakeside capital on Lake Xolotlán, spread low around the ruins of its old centre, with volcanic lagoons set into its southern hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Managua-panorama.jpg?width=1024"},{"name":"Belize City","rarity":"common","id":"belize-city","subtitle":"Belize","details":"A Caribbean port at the Belize River's mouth, of clapboard houses on canals, swing bridges and boats leaving for the offshore cayes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Belize_Aerial_14_%285343386895%29.jpg?width=1024"},{"name":"Oaxaca","rarity":"common","id":"oaxaca","subtitle":"Mexico","details":"A colonial valley city of green-stone churches and markets famed across Mexico for mole, mezcal and the Zapotec heritage of Monte Albán.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_cerro_del_Fortin.jpg?width=1024"},{"name":"Guadalajara","rarity":"common","id":"guadalajara","subtitle":"Mexico","details":"Birthplace of mariachi and tequila culture, a highland city of cathedral spires, murals and plazas in the Atemajac valley of Jalisco.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guadalajara_skyline.jpg?width=1024"},{"name":"Monterrey","rarity":"common","id":"monterrey","subtitle":"Mexico","details":"A northern industrial giant ringed by dramatic peaks, watched over by the flat-topped Cerro de la Silla, its unmistakable emblem.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monterrey_panorama_banner.jpg?width=1024"},{"name":"Mérida","rarity":"common","id":"merida","subtitle":"Mexico","details":"The White City of Yucatán, a colonial grid of limestone mansions on the Paseo de Montejo, gateway to the Maya world of cenotes and ruins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_M%C3%A9rida_Yucatan.jpg?width=1024"},{"name":"Puebla","rarity":"common","id":"puebla","subtitle":"Mexico","details":"A Talavera-tiled colonial city between volcanoes, famed for its many church domes, mole poblano and the great pyramid nearby at Cholula.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Centro_Hist%C3%B3rico_de_Puebla_desde_el_aire.jpg?width=1024"},{"name":"Arequipa","rarity":"common","id":"arequipa","subtitle":"Peru","details":"The White City built from pale sillar volcanic stone, spread on a high plain beneath the perfect cone of El Misti and two sister volcanoes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/28690-_Arequipa_and_the_Mitla_and_Chachani_volcanoes.jpg?width=1024"},{"name":"Valparaíso","rarity":"common","id":"valparaiso","subtitle":"Chile","details":"A Pacific port of steep colourful hills climbed by funiculars, where labyrinthine streets of painted houses overlook the working harbour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cerro_Baron%2C_Valparaiso%2C_Chile.JPG?width=1024"},{"name":"Córdoba","rarity":"common","id":"cordoba-argentina","subtitle":"Argentina","details":"Argentina's second city in the Sierras foothills, home to the country's oldest university and a Jesuit block of colonial churches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_of_downtown_Cordoba_city%2C_Argentina_2013-02-24.jpg?width=1024"},{"name":"Willemstad","rarity":"common","id":"willemstad","subtitle":"Curaçao","details":"A Dutch Caribbean port whose Handelskade row of gabled, candy-coloured warehouses lines the harbour channel behind a floating bridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Handelskade_Willemstad_-_Curacao.jpg?width=1024"},{"name":"Oranjestad","rarity":"common","id":"oranjestad","subtitle":"Aruba","details":"Aruba's capital, a compact port of Dutch colonial gables and pastel facades, where cruise ships dock beside its colourful main street.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Main_port_of_Aruba_%2813256378895%29.jpg?width=1024"},{"name":"San Pedro Sula","rarity":"common","id":"san-pedro-sula","subtitle":"Honduras","details":"Honduras' industrial engine in the Sula Valley, ringed by the green Merendón mountains and built on banana-trade wealth of the coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/San_Pedro_Sula%2C_Honduras.jpg?width=1024"},{"name":"Windhoek","rarity":"common","id":"windhoek","subtitle":"Namibia","details":"Namibia's capital nestles in a basin of the Khomas Hochland, where German-era churches stand among modern towers and dry hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Windhoek-Panorama.jpg?width=1024"},{"name":"Gaborone","rarity":"common","id":"gaborone","subtitle":"Botswana","details":"Botswana's capital spreads beneath Kgale Hill along the Notwane River, a planned city of government enclaves and shopping arcades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gaborone%20skyline.JPG?width=1024"},{"name":"Luanda","rarity":"common","id":"luanda","subtitle":"Angola","details":"Angola's capital curves around a bay and the Ilha peninsula, its skyline reshaped by towers above the old Portuguese fortress.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20baixa%20Luanda.JPG?width=1024"},{"name":"Kinshasa","rarity":"common","id":"kinshasa","subtitle":"Democratic Republic of the Congo","details":"The Congo River's great capital faces Brazzaville across the water, a vast city of markets, music and broad riverside boulevards.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2010-03-07-Kinshasa%20depuis%20Brazzaville.jpg?width=1024"},{"name":"Abidjan","rarity":"common","id":"abidjan","subtitle":"Côte d'Ivoire","details":"Côte d'Ivoire's economic capital rises on lagoon peninsulas, its Plateau district towers reflected in the Ébrié Lagoon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20HKB%20panorama%20Plateau.jpg?width=1024"},{"name":"Bamako","rarity":"common","id":"bamako","subtitle":"Mali","details":"Mali's capital stretches along both banks of the Niger River, a city of red earth, grand markets and the cliffs of Point G.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bamako%20ACI%202000%20Aeriel.jpg?width=1024"},{"name":"Ouagadougou","rarity":"common","id":"ouagadougou","subtitle":"Burkina Faso","details":"Burkina Faso's capital fans out across a flat savanna plain, home to the FESPACO film festival and a great central market.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Avenue%20a%20Ouagadougou.jpg?width=1024"},{"name":"Conakry","rarity":"common","id":"conakry","subtitle":"Guinea","details":"Guinea's capital squeezes along the narrow Kaloum peninsula into the Atlantic, a port city of markets, mosques and ocean breezes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guinean%20region%20of%20Conakry%20%28ISS022-E-31358%29.jpg?width=1024"},{"name":"Freetown","rarity":"common","id":"freetown","subtitle":"Sierra Leone","details":"Sierra Leone's capital climbs green hills around a vast natural harbour, anchored by its famous centuries-old cotton tree site.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Freetown-aerialview.jpg?width=1024"},{"name":"Monrovia","rarity":"common","id":"monrovia","subtitle":"Liberia","details":"Liberia's capital spreads across the Mesurado peninsula between the Atlantic and its river, founded by freed American settlers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monrovia%20-%20Panorama%202.jpg?width=1024"},{"name":"Banjul","rarity":"common","id":"banjul","subtitle":"Gambia","details":"Gambia's island capital sits at the mouth of the Gambia River, a small port city of the Arch 22 monument and Albert Market.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Banjul%20Gambia%20skyline.jpg?width=1024"},{"name":"Yaoundé","rarity":"common","id":"yaounde","subtitle":"Cameroon","details":"Cameroon's capital rolls over seven green hills in the central plateau, a city of red-earth streets and forested ridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Centre%20ville%20Yaound%C3%A9%20Cameroun.jpg?width=1024"},{"name":"Libreville","rarity":"common","id":"libreville","subtitle":"Gabon","details":"Gabon's capital lines the Komo estuary on the Atlantic, a city of carved totems, beaches and the presidential palace seafront.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Libreville%20immeubles.jpg?width=1024"},{"name":"Asmara","rarity":"common","id":"asmara","subtitle":"Eritrea","details":"Eritrea's highland capital preserves an extraordinary collection of Italian modernist architecture along its palm-lined avenues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Asmara%20Panorama.JPG?width=1024"},{"name":"Djibouti City","rarity":"common","id":"djibouti-city","subtitle":"Djibouti","details":"Djibouti's port capital guards the Bab el-Mandeb gateway between the Red Sea and the Gulf of Aden, a hub of shipping lanes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20of%20Rue%20Marchand%2C%20Djibouti%20City.JPG?width=1024"},{"name":"Mogadishu","rarity":"common","id":"mogadishu","subtitle":"Somalia","details":"Somalia's White Pearl of the Indian Ocean lines a coral coast with old stone quarters, lighthouse ruins and long fishing beaches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20View%20of%20Somalia%2C%20As%20Seen%20From%20the%20Aircraft%20Carrying%20Secretary%20Kerry%20on%20May%206%2C%202015%20%2817193204170%29.jpg?width=1024"},{"name":"Victoria","rarity":"common","id":"victoria-seychelles","subtitle":"Seychelles","details":"The Seychelles capital tucks beneath granite peaks on Mahé island, its harbour, clock tower and markets facing turquoise bays.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Port-victoria%20Seychelles.jpg?width=1024"},{"name":"Port Louis","rarity":"common","id":"port-louis","subtitle":"Mauritius","details":"Mauritius's capital fills a natural harbour ringed by the Moka mountains, a port city of temples, markets and Champ de Mars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20of%20Port%20Louis%20Waterfront%20%284716846715%29.jpg?width=1024"},{"name":"Arusha","rarity":"common","id":"arusha","subtitle":"Tanzania","details":"Tanzania's safari capital lies in the shadow of Mount Meru, a green highland city at the gateway to Serengeti and Kilimanjaro.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cityscape%2C%20Sekei%20Ward%2C%20Arusha%20Urban%20District.jpg?width=1024"},{"name":"Gold Coast","rarity":"common","id":"gold-coast","subtitle":"Australia","details":"Queensland resort city of surf beaches and winding canals, its high-rise strip at Surfers Paradise set behind a long golden arc of Pacific shoreline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gold%20Coast%20skyline%202012.jpg?width=1024"},{"name":"Cairns","rarity":"common","id":"cairns","subtitle":"Australia","details":"Tropical port in far north Queensland founded in 1876, gateway to the Great Barrier Reef and the ancient Wet Tropics rainforests of the hinterland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cairns%20Skyline%20Valley%20Rain.jpg?width=1024"},{"name":"Alice Springs","rarity":"common","id":"alice-springs","subtitle":"Australia","details":"Remote desert town in central Australia's MacDonnell Ranges, founded as an Overland Telegraph station on the usually dry bed of the Todd River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alice%20Springs%20panorama.JPG?width=1024"},{"name":"Hamilton","rarity":"common","id":"hamilton","subtitle":"New Zealand","details":"Inland Waikato city on New Zealand's longest river, founded in 1864, a farming and university centre famed for its themed public gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HamCBDfromHillcrest.JPG?width=1024"},{"name":"Tauranga","rarity":"common","id":"tauranga","subtitle":"New Zealand","details":"Harbour city on the Bay of Plenty beneath the volcanic cone of Mount Maunganui, a major export port ringed by orchards, beaches and surf breaks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Maunganui%20Main%20Beach%2C%202013%20%2801%29.jpg?width=1024"},{"name":"Port Moresby","rarity":"common","id":"port-moresby","subtitle":"Papua New Guinea","details":"Papua New Guinea's capital, grown from an 1873 trading post on a sheltered harbour of dry hills and bays along the Papuan Peninsula coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/POM%20Downtown.jpg?width=1024"},{"name":"Apia","rarity":"common","id":"apia","subtitle":"Samoa","details":"Samoa's capital and main port on Upolu's north coast, a harbour town of white churches, markets and colonial buildings behind a reef-sheltered lagoon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Apia%2C%20Samoa%2C%20with%20rainbow%20-%20August%202016.jpg?width=1024"},{"name":"Carthage","rarity":"common","id":"carthage","subtitle":"Tunisia","details":"Phoenician-founded maritime power near modern Tunis and Rome's great rival, destroyed in 146 BC and rebuilt as a Roman city of baths, villas and ports.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ruins%20near%20Carthage%20national%20museum%2C%20Tunisia.jpg?width=1024"},{"name":"Mohenjo-daro","rarity":"common","id":"mohenjo-daro","subtitle":"Pakistan","details":"One of the largest Indus Valley cities, built in baked brick around 2600 BC with grid streets, covered drains and a ritual Great Bath on a raised citadel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mohenjo-daro.jpg?width=1024"},{"name":"Ur","rarity":"common","id":"ur","subtitle":"Iraq","details":"Sumerian city-state in southern Iraq at its height in the third millennium BC, famed for its great stepped ziggurat and royal tombs filled with gold.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ancient%20ziggurat%20at%20Ali%20Air%20Base%20Iraq%202005.jpg?width=1024"},{"name":"Great Zimbabwe","rarity":"common","id":"great-zimbabwe","subtitle":"Zimbabwe","details":"Medieval capital of a gold-trading Shona kingdom, built between the 11th and 15th centuries; its Great Enclosure is ancient Africa's largest stone ruin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great-zim-aerial-looking-West.JPG?width=1024"},{"name":"Cahokia","rarity":"common","id":"cahokia","subtitle":"United States","details":"The largest pre-Columbian city north of Mexico, a Mississippian centre by the Mississippi whose great Monks Mound rises over plazas and palisade lines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monks%20Mound%20-%20Summer%202024.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
